with open('alerts.html', 'r') as f:
    html = f.read()

# Replace paths block
m = re.search(
    r'(<g class="map-oblasts"[^>]*>)(.*?)(</g>\s*\n\s*<!-- Sea of Azov)',
    html, re.DOTALL)
if m:
    html = html[:m.start(2)] + '\n' + PATHS + '\n                ' + html[m.start(3):]
    print('✓ paths replaced')

# Replace labels block
m2 = re.search(
    r'(<g class="map-oblast-labels"[^>]*>)(.*?)(</g>\s*\n\s*<!-- Kyiv capital)',
    html, re.DOTALL)
if m2:
    html = html[:m2.start(2)] + '\n' + LABELS + '\n                ' + html[m2.start(3):]
    print('✓ labels replaced')

with open('alerts.html', 'w') as f:
    f.write(html)

print('Done')
